import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(2)
    ch.send(1)
    ch.send(2)
    let a = ch.receive()
    let b = ch.receive()
    match a {
        Some(x) => {
            if x == 1 {
                io.println("a1")
            } else {
                io.println("ax")
            }
        }
        None => { io.println("anone") }
    }
    match b {
        Some(x) => {
            if x == 2 {
                io.println("b2")
            } else {
                io.println("bx")
            }
        }
        None => { io.println("bnone") }
    }
    return Ok(())
}
